1	// POST /groups/:id/import: records a list of expenses and payments in one go, all of them or none of them.
2	// Same contract as the other handlers: it returns a new store instead of changing the one it gets.
3	import { NOT_FOUND, findGroup } from './groups.mjs'
4	import { balances, expenseView, paymentView } from './ledger.mjs'
5	import { parseAmount, parseDescription, parseMember, parseSplit, ValidationError } from './validate.mjs'
6	
7	const MAX_ENTRIES = 50
8	const BODY_FIELDS = ['entries', 'dry_run', 'skip_recorded']
9	const ENTRY_FIELDS = {
10	  expense: ['type', 'description', 'payer', 'amount', 'split'],
11	  payment: ['type', 'from', 'to', 'amount'],
12	}
13	
14	const isObject = v => v !== null && typeof v === 'object' && !Array.isArray(v)
15	
16	// Runs parse(); on a ValidationError throws the import rule instead, so an entry stops at its first broken rule.
17	class RuleBroken extends Error {}
18	function check(rule, parse) {
19	  try {
20	    return parse()
21	  } catch (err) {
22	    if (err instanceof ValidationError) throw new RuleBroken(rule)
23	    throw err
24	  }
25	}
26	
27	// Two expenses are the same when payer, amount in cents and trimmed lower-cased description match.
28	const sameKey = ({ description, payer, amount }) => JSON.stringify([payer, amount, description.trim().toLowerCase()])
29	
30	function parseBody(body) {
31	  const unknown = Object.keys(body).find(key => !BODY_FIELDS.includes(key))
32	  if (unknown !== undefined) throw new ValidationError(`unknown field ${unknown}`)
33	  const { entries } = body
34	  if (!Array.isArray(entries) || entries.length < 1 || entries.length > MAX_ENTRIES) {
35	    throw new ValidationError(`entries must be an array of 1 to ${MAX_ENTRIES} items`)
36	  }
37	  for (const flag of ['dry_run', 'skip_recorded']) {
38	    if (flag in body && typeof body[flag] !== 'boolean') throw new ValidationError(`${flag} must be true or false`)
39	  }
40	  return { entries, dryRun: body.dry_run === true, skipRecorded: body.skip_recorded === true }
41	}
42	
43	// The fields of one entry as { type, fields }, or throws RuleBroken with the first rule it breaks before the
44	// duplicate checks.
45	function parseEntry(group, entry) {
46	  if (!isObject(entry)) throw new RuleBroken('not-an-object')
47	  if (entry.type !== 'expense' && entry.type !== 'payment') throw new RuleBroken('bad-type')
48	  if (Object.keys(entry).some(key => !ENTRY_FIELDS[entry.type].includes(key))) throw new RuleBroken('unknown-field')
49	  if (entry.type === 'expense') {
50	    return {
51	      type: 'expense',
52	      fields: {
53	        description: check('bad-description', () => parseDescription(entry.description)),
54	        payer: check('bad-payer', () => parseMember(entry.payer, group.members, 'payer')),
55	        amount: check('bad-amount', () => parseAmount(entry.amount)),
56	        split: check('bad-split', () => parseSplit(entry.split, group.members)),
57	      },
58	    }
59	  }
60	  const from = check('bad-from', () => parseMember(entry.from, group.members, 'from'))
61	  const to = check('bad-to', () => parseMember(entry.to, group.members, 'to'))
62	  if (to === from) throw new RuleBroken('bad-to')
63	  return { type: 'payment', fields: { from, to, amount: check('bad-amount', () => parseAmount(entry.amount)) } }
64	}
65	
66	export function importEntries({ state, params, body }) {
67	  const group = findGroup(state, params[0])
68	  if (!group) return NOT_FOUND
69	  const { entries, dryRun, skipRecorded } = parseBody(body)
70	
71	  const recorded = new Set(state.expenses.filter(e => e.group === group.id).map(sameKey))
72	  const seen = new Set()
73	  const problems = []
74	  const skipped = []
75	  const expenses = []
76	  const payments = []
77	  entries.forEach((entry, index) => {
78	    let parsed
79	    try {
80	      parsed = parseEntry(group, entry)
81	    } catch (err) {
82	      if (!(err instanceof RuleBroken)) throw err
83	      problems.push({ index, rule: err.message })
84	      return
85	    }
86	    const { type, fields } = parsed
87	    if (type === 'payment') {
88	      payments.push({ id: state.nextPaymentId + payments.length, group: group.id, ...fields })
89	      return
90	    }
91	    const key = sameKey(fields)
92	    const isDuplicate = seen.has(key)
93	    seen.add(key)
94	    if (isDuplicate) problems.push({ index, rule: 'duplicate' })
95	    else if (recorded.has(key) && skipRecorded) skipped.push(index)
96	    else if (recorded.has(key)) problems.push({ index, rule: 'already-recorded' })
97	    else expenses.push({ id: state.nextExpenseId + expenses.length, group: group.id, ...fields })
98	  })
99	  if (problems.length > 0) return { status: 422, body: { error: 'import rejected', problems } }
100	
101	  const next = {
102	    ...state,
103	    expenses: [...state.expenses, ...expenses],
104	    payments: [...state.payments, ...payments],
105	    nextExpenseId: state.nextExpenseId + expenses.length,
106	    nextPaymentId: state.nextPaymentId + payments.length,
107	  }
108	  const reply = {
109	    status: dryRun ? 200 : 201,
110	    body: {
111	      expenses: expenses.map(expenseView),
112	      payments: payments.map(paymentView),
113	      skipped,
114	      balances: balances(next, group),
115	    },
116	  }
117	  // A dry run, or an import whose entries were all skipped, writes nothing.
118	  const changed = expenses.length > 0 || payments.length > 0
119	  return dryRun || !changed ? reply : { ...reply, state: next }
120	}
121

1	// Input checks for request bodies and query strings. Each parser returns the clean value or throws a
2	// ValidationError, which the server turns into a 400 reply.
3	
4	export class ValidationError extends Error {
5	  constructor(message) {
6	    super(message)
7	    this.name = 'ValidationError'
8	  }
9	}
10	
11	const GROUP_ID = /^[a-z][a-z0-9-]{0,29}$/
12	const MEMBER_NAME = /^[A-Za-z][A-Za-z0-9_-]{0,29}$/
13	const MIN_MEMBERS = 2
14	const MAX_MEMBERS = 20
15	const MAX_GROUP_NAME_LENGTH = 100
16	const MAX_DESCRIPTION_LENGTH = 200
17	const CENTS_PER_UNIT = 100
18	const MAX_AMOUNT_CENTS = 1_000_000 * CENTS_PER_UNIT
19	// Digits with at most two decimals, as String() writes a number: "12", "12.5", "4.35".
20	const TWO_DECIMALS = /^[0-9]+(\.[0-9]{1,2})?$/
21	
22	const AMOUNT_MESSAGE = 'amount must be a number from 0.01 to 1000000 with at most 2 decimals'
23	const SPLIT_MESSAGE = 'split must be a non-empty list of different members of the group'
24	
25	const isText = (v, max) => typeof v === 'string' && v.trim() !== '' && v.length <= max
26	
27	export function parseGroupId(v) {
28	  if (typeof v !== 'string' || !GROUP_ID.test(v)) {
29	    throw new ValidationError('id must be 1 to 30 characters of a-z, 0-9 or -, starting with a letter')
30	  }
31	  return v
32	}
33	
34	export function parseGroupName(v) {
35	  if (!isText(v, MAX_GROUP_NAME_LENGTH)) {
36	    throw new ValidationError(`name must be a non-empty string of at most ${MAX_GROUP_NAME_LENGTH} characters`)
37	  }
38	  return v
39	}
40	
41	// A list of 2 to 20 member names, each used once. Names are case-sensitive: "Ann" and "ann" are two people.
42	export function parseMembers(v) {
43	  if (!Array.isArray(v) || v.length < MIN_MEMBERS || v.length > MAX_MEMBERS) {
44	    throw new ValidationError(`members must be an array of ${MIN_MEMBERS} to ${MAX_MEMBERS} names`)
45	  }
46	  if (!v.every(name => typeof name === 'string' && MEMBER_NAME.test(name))) {
47	    throw new ValidationError('member names must be 1 to 30 characters of A-Z, a-z, 0-9, _ or -, starting with a letter')
48	  }
49	  if (new Set(v).size !== v.length) throw new ValidationError('members must not repeat a name')
50	  return [...v]
51	}
52	
53	export function parseDescription(v) {
54	  if (!isText(v, MAX_DESCRIPTION_LENGTH)) {
55	    throw new ValidationError(`description must be a non-empty string of at most ${MAX_DESCRIPTION_LENGTH} characters`)
56	  }
57	  return v
58	}
59	
60	// Amounts arrive as numbers such as 12.5 or 4.35 and are kept as whole cents, so sums never drift.
61	export function parseAmount(v) {
62	  if (typeof v !== 'number' || !TWO_DECIMALS.test(String(v))) throw new ValidationError(AMOUNT_MESSAGE)
63	  // Rounded, not truncated: 4.35 * 100 is 434.99999999999994 in floating point.
64	  const cents = Math.round(v * CENTS_PER_UNIT)
65	  if (cents < 1 || cents > MAX_AMOUNT_CENTS) throw new ValidationError(AMOUNT_MESSAGE)
66	  return cents
67	}
68	
69	// A name that must belong to one of members; message says which field was wrong.
70	export function parseMember(v, members, message) {
71	  if (typeof v !== 'string' || !members.includes(v)) throw new ValidationError(message)
72	  return v
73	}
74	
75	// Who shares an expense: a non-empty list of members without repeats. Missing means every member, in group order.
76	export function parseSplit(v, members) {
77	  if (v === undefined) return [...members]
78	  if (!Array.isArray(v) || v.length === 0 || new Set(v).size !== v.length) throw new ValidationError(SPLIT_MESSAGE)
79	  if (!v.every(name => typeof name === 'string' && members.includes(name))) throw new ValidationError(SPLIT_MESSAGE)
80	  return [...v]
81	}
82

1	// Expense and payment handlers, same contract as lib/groups.mjs: they return a new store instead of changing
2	// the one they get.
3	import { NOT_FOUND, findGroup } from './groups.mjs'
4	import { expenseView, paymentView } from './ledger.mjs'
5	import { parseAmount, parseDescription, parseMember, parseSplit, ValidationError } from './validate.mjs'
6	
7	const byId = (a, b) => a.id - b.id
8	
9	// The fields of a new expense in group, from a request body. Throws ValidationError on the first bad field.
10	export function parseExpense(group, body) {
11	  return {
12	    description: parseDescription(body.description),
13	    payer: parseMember(body.payer, group.members, 'payer must be a member of the group'),
14	    amount: parseAmount(body.amount),
15	    split: parseSplit(body.split, group.members),
16	  }
17	}
18	
19	export function addExpense({ state, params, body }) {
20	  const group = findGroup(state, params[0])
21	  if (!group) return NOT_FOUND
22	  const expense = { id: state.nextExpenseId, group: group.id, ...parseExpense(group, body) }
23	  const next = { ...state, expenses: [...state.expenses, expense], nextExpenseId: state.nextExpenseId + 1 }
24	  return { status: 201, body: expenseView(expense), state: next }
25	}
26	
27	export function listExpenses({ state, params }) {
28	  const group = findGroup(state, params[0])
29	  if (!group) return NOT_FOUND
30	  const expenses = state.expenses.filter(e => e.group === group.id).sort(byId).map(expenseView)
31	  return { status: 200, body: { expenses } }
32	}
33	
34	const findExpense = (state, [groupId, expenseId]) =>
35	  state.expenses.find(e => e.group === groupId && String(e.id) === expenseId)
36	
37	// Changes the fields the body gives, each checked as on POST; fields left out keep their value.
38	export function editExpense({ state, params, body }) {
39	  const group = findGroup(state, params[0])
40	  const old = group && findExpense(state, params)
41	  if (!old) return NOT_FOUND
42	  const changes = {}
43	  if ('description' in body) changes.description = parseDescription(body.description)
44	  if ('payer' in body) changes.payer = parseMember(body.payer, group.members, 'payer must be a member of the group')
45	  if ('amount' in body) changes.amount = parseAmount(body.amount)
46	  if ('split' in body) changes.split = parseSplit(body.split, group.members)
47	  const edited = { ...old, ...changes }
48	  const next = { ...state, expenses: state.expenses.map(e => (e === old ? edited : e)) }
49	  return { status: 200, body: expenseView(edited), state: next }
50	}
51	
52	export function deleteExpense({ state, params }) {
53	  const expense = findExpense(state, params)
54	  if (!expense) return NOT_FOUND
55	  return { status: 204, state: { ...state, expenses: state.expenses.filter(e => e !== expense) } }
56	}
57	
58	export function addPayment({ state, params, body }) {
59	  const group = findGroup(state, params[0])
60	  if (!group) return NOT_FOUND
61	  const message = 'from and to must be two different members of the group'
62	  const from = parseMember(body.from, group.members, message)
63	  const to = parseMember(body.to, group.members, message)
64	  if (from === to) throw new ValidationError(message)
65	  const payment = { id: state.nextPaymentId, group: group.id, from, to, amount: parseAmount(body.amount) }
66	  const next = { ...state, payments: [...state.payments, payment], nextPaymentId: state.nextPaymentId + 1 }
67	  return { status: 201, body: paymentView(payment), state: next }
68	}
69	
70	export function listPayments({ state, params }) {
71	  const group = findGroup(state, params[0])
72	  if (!group) return NOT_FOUND
73	  const payments = state.payments.filter(p => p.group === group.id).sort(byId).map(paymentView)
74	  return { status: 200, body: { payments } }
75	}
76

1	// The data file: { groups, expenses, payments, nextExpenseId, nextPaymentId } as JSON.
2	import { readFileSync, renameSync, rmSync, writeFileSync } from 'node:fs'
3	
4	export const emptyStore = () => ({ groups: [], expenses: [], payments: [], nextExpenseId: 1, nextPaymentId: 1 })
5	
6	const hasShape = data =>
7	  Array.isArray(data?.groups) &&
8	  Array.isArray(data.expenses) &&
9	  Array.isArray(data.payments) &&
10	  Number.isInteger(data.nextExpenseId) &&
11	  Number.isInteger(data.nextPaymentId)
12	
13	// Reads the store from file. A missing file is an empty store; a damaged file is an error.
14	export function load(file) {
15	  let text
16	  try {
17	    text = readFileSync(file, 'utf8')
18	  } catch (err) {
19	    if (err.code === 'ENOENT') return emptyStore()
20	    throw err
21	  }
22	  let data
23	  try {
24	    data = JSON.parse(text)
25	  } catch {
26	    throw new Error(`data file ${file} is not valid JSON`)
27	  }
28	  if (!hasShape(data)) throw new Error(`data file ${file} has an unexpected shape`)
29	  return data
30	}
31	
32	// Writes the store atomically: a temp file next to the target, then a rename over it.
33	export function save(file, data) {
34	  const tmp = `${file}.${process.pid}.tmp`
35	  writeFileSync(tmp, JSON.stringify(data, null, 2) + '\n')
36	  try {
37	    renameSync(tmp, file)
38	  } catch (err) {
39	    rmSync(tmp, { force: true })
40	    throw err
41	  }
42	}
43

1	// HTTP helpers: reading a JSON body, sending JSON replies and turning errors into replies.
2	import { ValidationError } from './validate.mjs'
3	
4	export const MAX_BODY_BYTES = 10 * 1024
5	
6	export class HttpError extends Error {
7	  constructor(status, message) {
8	    super(message)
9	    this.status = status
10	  }
11	}
12	
13	// Reads the whole body as UTF-8. Past MAX_BODY_BYTES it stops keeping chunks but still drains the upload,
14	// so the 413 reply reaches the client instead of a reset connection.
15	export function readBody(req) {
16	  return new Promise((resolve, reject) => {
17	    const chunks = []
18	    let size = 0
19	    req.on('data', chunk => {
20	      size += chunk.length
21	      if (size <= MAX_BODY_BYTES) chunks.push(chunk)
22	    })
23	    req.on('end', () => {
24	      if (size > MAX_BODY_BYTES) reject(new HttpError(413, 'body too large'))
25	      else resolve(Buffer.concat(chunks).toString('utf8'))
26	    })
27	    req.on('error', reject)
28	  })
29	}
30	
31	export function parseJsonObject(text) {
32	  let value
33	  try {
34	    value = JSON.parse(text)
35	  } catch {
36	    throw new HttpError(400, 'invalid JSON')
37	  }
38	  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
39	    throw new HttpError(400, 'body must be a JSON object')
40	  }
41	  return value
42	}
43	
44	// Sends { status, body }: body as JSON, or no body at all when it is undefined (204).
45	export function send(res, { status, body }) {
46	  if (body === undefined) {
47	    res.writeHead(status).end()
48	    return
49	  }
50	  const text = JSON.stringify(body)
51	  res.writeHead(status, { 'content-type': 'application/json', 'content-length': Buffer.byteLength(text) })
52	  res.end(text)
53	}
54	
55	export function errorReply(err) {
56	  if (err instanceof HttpError) return { status: err.status, body: { error: err.message } }
57	  if (err instanceof ValidationError) return { status: 400, body: { error: err.message } }
58	  // An OS error (ENOENT, EACCES, ...) is logged as one line; any other error keeps its stack.
59	  console.error(err.code ? [err.code, err.syscall, err.path].filter(Boolean).join(' ') : err)
60	  return { status: 500, body: { error: 'internal error' } }
61	}
62

1	// Group handlers. A handler gets { state, params, query, body } and returns { status, body } plus, when it
2	// changes the store, the new store as `state`. Handlers never change the state they are given.
3	import { balances, settleUp } from './ledger.mjs'
4	import { parseGroupId, parseGroupName, parseMembers } from './validate.mjs'
5	
6	export const NOT_FOUND = { status: 404, body: { error: 'not found' } }
7	
8	export const findGroup = (state, id) => state.groups.find(g => g.id === id)
9	
10	export function createGroup({ state, body }) {
11	  const group = { id: parseGroupId(body.id), name: parseGroupName(body.name), members: parseMembers(body.members) }
12	  if (findGroup(state, group.id)) return { status: 409, body: { error: 'group already exists' } }
13	  return { status: 201, body: group, state: { ...state, groups: [...state.groups, group] } }
14	}
15	
16	export function getGroup({ state, params }) {
17	  const group = findGroup(state, params[0])
18	  return group ? { status: 200, body: group } : NOT_FOUND
19	}
20	
21	export function getBalances({ state, params }) {
22	  const group = findGroup(state, params[0])
23	  if (!group) return NOT_FOUND
24	  return { status: 200, body: { balances: balances(state, group) } }
25	}
26	
27	export function getSettleUp({ state, params }) {
28	  const group = findGroup(state, params[0])
29	  if (!group) return NOT_FOUND
30	  return { status: 200, body: { payments: settleUp(state, group) } }
31	}
32

1	import { mkdtempSync, rmSync } from 'node:fs'
2	import { tmpdir } from 'node:os'
3	import { join } from 'node:path'
4	import { createApp } from '../server.mjs'
5	
6	// A data file in a fresh temp folder; cleanup() deletes the folder.
7	export function tempDataFile() {
8	  const dir = mkdtempSync(join(tmpdir(), 'split-test-'))
9	  return { file: join(dir, 'groups.json'), cleanup: () => rmSync(dir, { recursive: true, force: true }) }
10	}
11	
12	// Starts the app on a free port. call(method, path, body) sends one request; stop() closes the server.
13	export async function startApp(dataFile) {
14	  const server = createApp(dataFile)
15	  await new Promise((resolve, reject) => {
16	    server.once('error', reject)
17	    server.listen(0, '127.0.0.1', resolve)
18	  })
19	  const base = `http://127.0.0.1:${server.address().port}`
20	  return {
21	    call: (method, path, body) => request(base + path, method, body),
22	    stop: () => new Promise(resolve => server.close(resolve)),
23	  }
24	}
25	
26	// Runs fn with a running app on its own data file, then stops it and deletes the file.
27	export async function withApp(fn) {
28	  const data = tempDataFile()
29	  const app = await startApp(data.file)
30	  try {
31	    await fn(app.call)
32	  } finally {
33	    await app.stop()
34	    data.cleanup()
35	  }
36	}
37	
38	async function request(url, method, body) {
39	  const init = { method }
40	  if (body !== undefined) {
41	    init.headers = { 'content-type': 'application/json' }
42	    init.body = typeof body === 'string' ? body : JSON.stringify(body)
43	  }
44	  const res = await fetch(url, init)
45	  const text = await res.text()
46	  const isJson = (res.headers.get('content-type') ?? '').startsWith('application/json')
47	  return { status: res.status, headers: res.headers, text, body: isJson ? JSON.parse(text) : undefined }
48	}
